-- Icelandic texts for the meal library (translated + proofread 2026-09-30).
update public.meals m set name_is = v.n, description_is = v.d, ingredients_is = v.i, instructions_is = v.s
from (values
('7593531f-f4f7-4042-93d9-3af73f31cf51'::uuid, 'Próteinrík berjaskál', 'Svo þykkur þeytingur með mysupróteini að hann er borðaður með skeið, með hnetusmjöri og granóla ofan á.', array['1 banani','150 g frosin blönduð ber','30 g mysuprótein','2 dl haframjólk','30 g hnetusmjör','30 g granóla']::text[], array['Blandaðu banana, berjum, mysupróteini og mjólk saman þar til blandan er orðin þykk','Settu í skál með skeið','Settu hnetusmjör og granóla ofan á']::text[]),
('04262c6f-243b-4cc9-96ca-de59108fa474'::uuid, 'Morgunpanna með kjúklingi', 'Kjúklingabitar með sætri kartöflu og papriku — matarmikil byrjun á deginum með góðum próteinskammti.', array['200 g eldað kjúklingalæri, skorið í bita','200 g sæt kartafla, skorin í teninga','1 paprika, smátt skorin','1 msk. ólífuolía','reykt paprikuduft','salt']::text[], array['Bakaðu sætu kartöfluna í ofni í 20 mín. við 200 °C','Steiktu papriku og kjúkling upp úr olíunni','Blandaðu öllu saman og kryddaðu með paprikudufti']::text[]),
('68a8a7cb-65c5-40a9-9c15-f6843bbe6494'::uuid, 'Kotasæla með reyktum laxi', 'Próteinríkur diskur sem þarf ekki að elda — kotasæla, reyktur lax, agúrka og dill.', array['200 g kotasæla','100 g reyktur lax','½ agúrka, sneidd','ferskt dill','svartur pipar']::text[], array['Settu kotasæluna á disk','Raðaðu laxi og agúrku á diskinn','Stráðu dilli og pipar yfir']::text[]),
('ecbcb86e-338e-4aaf-a329-db2a73e5c7b3'::uuid, 'Kotasæluskál', '40 g af próteini og engin eldamennska. Uppáhald lata vaxtarræktarmannsins.', array['225 g kotasæla','80 g ananas','2 msk. valhnetur','1 tsk. hunang']::text[], array['Settu kotasæluna í skál.','Settu ananas og valhnetur ofan á.','Dreifðu hunangi yfir.']::text[]),
('19834ff0-e98e-48fc-9b00-b44123f5278e'::uuid, 'Kotasælulummur', 'Kotasæla, egg og haframjöl maukað saman í próteinríkar lummur.', array['250 g kotasæla','2 egg','40 g haframjöl','1 tsk. vanilludropar','1 tsk. ólífuolía á pönnuna']::text[], array['Maukaðu kotasælu, egg, haframjöl og vanilludropa saman','Hitaðu pönnu með olíu','Steiktu litlar lummur í 2 mín. á hvorri hlið']::text[]),
('0c0fb6cf-c613-4c97-aef3-97f962d6b990'::uuid, 'Fimm eggja eggjakaka með spínati', 'Fljótleg og próteinrík eggjakaka með fetaosti og mýktu spínati.', array['5 stór egg','60 g fetaostur','100 g spínat','1 tsk. ólífuolía','salt','svartur pipar']::text[], array['Hitaðu olíuna á pönnu','Láttu spínatið mýkjast í 30 sek.','Helltu þeyttum eggjunum yfir','Myldu fetaostinn yfir','Brjóttu eggjakökuna saman og berðu fram']::text[]),
('f685fbb8-7178-4b3e-a640-b54a5e6d5a14'::uuid, 'Orkuskál með grískri jógúrt', 'Vegleg skál af grískri jógúrt með möndlum, chiafræjum og berjum.', array['300 g grísk jógúrt','30 g möndlur','15 g chiafræ','100 g blönduð ber','1 tsk. hunang']::text[], array['Settu jógúrtina í skál','Settu chiafræ, möndlur, ber og hunang ofan á']::text[]),
('7ed6876b-22a2-44dc-98c7-9fed152d32b7'::uuid, 'Grísk jógúrt með berjum og granóla', '30 g af próteini á 5 mínútum — engin eldamennska.', array['250 g grísk jógúrt (fullfeit)','80 g blönduð ber','2 msk. granóla','1 msk. hunang','1 msk. hnetusmjör']::text[], array['Settu jógúrtina í skál.','Settu ber, granóla og hnetusmjör ofan á.','Dreifðu hunangi yfir.','Borðaðu strax.']::text[]),
('9e5b87d9-8a93-4adf-8161-8b89614bc48c'::uuid, 'Próteinhafragrautur', 'Hafragrautur soðinn í mjólk og hrærður með mysupróteini — morgunmatur sem skilar miklu.', array['60 g haframjöl','3 dl mjólk','30 g mysuprótein','1 banani','1 msk. hnetusmjör','kanill']::text[], array['Láttu haframjöl og mjólk malla í 4 mín.','Taktu pottinn af hellunni og hrærðu','Hrærðu mysupróteininu saman við þegar grauturinn hefur kólnað aðeins','Settu banana, hnetusmjör og kanil ofan á']::text[]),
('7415c56d-c1d9-47ce-b2b7-b0ba6e5a93ca'::uuid, 'Próteingrautur með banana', 'Matarmikill morgunmatur með 35 g af próteini sem heldur þér söddum fram að hádegi.', array['40 g haframjöl','2,5 dl mjólk','1 skeið mysuprótein (um 30 g)','1 banani, sneiddur','1 msk. hnetusmjör','kanill']::text[], array['Settu haframjöl og mjólk í pott og láttu suðuna koma upp.','Láttu malla í 5 mínútur og hrærðu öðru hverju.','Taktu pottinn af hellunni og hrærðu próteinduftinu saman við.','Settu banana, hnetusmjör og kanil ofan á.']::text[]),
('11566e54-59ee-4efb-8361-e0bd065c0638'::uuid, 'Próteinþeytingur', 'Morgunmatur í glasi — tilvalinn á annasömum morgnum.', array['1 skeið mysuprótein (um 30 g)','1 banani','2,5 dl mjólk','1 msk. hnetusmjör','klakar']::text[], array['Settu allt hráefnið í blandara.','Blandaðu þar til þeytingurinn er sléttur.','Helltu í glas og drekktu.']::text[]),
('8c306328-4005-4ce3-ab57-c850b92b23f0'::uuid, 'Lax og hrærð egg', 'Pönnusteiktur lax með mjúkum hrærðum eggjum — kolvetnalítil og próteinrík máltíð.', array['150 g laxaflak','3 egg','1 tsk. smjör','graslaukur','salt','svartur pipar']::text[], array['Steiktu laxinn á pönnu í 3 mín. á hvorri hlið','Hrærðu eggin mjúk í smjörinu','Berðu fram með graslauk']::text[]),
('04bf8166-5c78-4c51-bb44-f4fc3b6b33e3'::uuid, 'Hrærð egg og avókadóbrauð', 'Sígildur og próteinríkur morgunmatur með hollri fitu.', array['3 egg','1 sneið súrdeigsbrauð, ristuð','½ avókadó','salt og pipar','1 tsk. ólífuolía','chiliflögur']::text[], array['Hitaðu ólífuolíuna á viðloðunarfrírri pönnu.','Þeyttu eggin með salti og pipar.','Helltu þeim á pönnuna og hrærðu þar til þau eru rétt stífnuð.','Ristaðu brauðið og settu stappað avókadó og chiliflögur ofan á.','Berðu eggin fram með.']::text[]),
('8268bfd7-8a40-4e0f-bcbe-da25a528724d'::uuid, 'Skyrskál með berjum', 'Tvöfaldur skammtur af skyri með berjum og granóla — mikið prótein með lítilli fyrirhöfn.', array['350 g hreint skyr','100 g blönduð ber','40 g granóla','1 msk. hunang']::text[], array['Settu skyrið í skál','Settu ber og granóla ofan á','Dreifðu hunangi yfir']::text[]),
('63999119-6add-48cf-97a1-56ea23750871'::uuid, 'Beygla með reyktum laxi', 'Prótein, ómega-3 og flókin kolvetni — góð byrjun á deginum.', array['1 gróf beygla','50 g reyktur lax','2 msk. rjómaostur','kapers','rauðlaukssneiðar','dill']::text[], array['Skerðu beygluna í tvennt og ristaðu hana.','Smyrðu rjómaosti á báða helmingana.','Settu lax, kapers, rauðlauk og dill ofan á.']::text[]),
('6ea8a483-77a9-4799-a22d-339c4f5aab9e'::uuid, 'Rúgbrauð með reyktum laxi', 'Rúgbrauð með reyktum laxi, linsoðnu eggi og dilli.', array['2 sneiðar rúgbrauð','150 g reyktur lax','2 egg','30 g rjómaostur','ferskt dill','sítrónubátur']::text[], array['Ristaðu rúgbrauðið','Linsjóddu eggin í 6 mín.','Smyrðu rjómaostinum á brauðið','Raðaðu laxi, eggjahelmingum og dilli ofan á']::text[]),
('f838ace7-2257-4eea-81f0-e02daa767c04'::uuid, 'Opin samloka með túnfiski og eggi', 'Túnfiskur úr dós og harðsoðin egg á rúgbrauði — fljótlegt prótein við skrifborðið.', array['1 dós túnfiskur í vatni (150 g)','2 harðsoðin egg','2 sneiðar rúgbrauð','1 msk. grísk jógúrt','1 tsk. dijon-sinnep','agúrkusneiðar']::text[], array['Helltu vatninu af túnfiskinum og stappaðu hann með jógúrt og sinnepi','Ristaðu rúgbrauðið','Settu túnfiskblönduna og eggjasneiðar ofan á']::text[]),
('3cb31fec-6116-4b41-8a63-b077aa4278b5'::uuid, 'Heilhveitibeygla með kalkún og avókadó', 'Magurt kalkúnaálegg og avókadó á ristaðri heilhveitibeyglu.', array['1 heilhveitibeygla','150 g kalkúnaálegg í sneiðum','½ avókadó','salatblöð','tómatur','1 tsk. dijon-sinnep']::text[], array['Ristaðu beygluna','Smyrðu sinnepinu á','Raðaðu kalkún, avókadói, salati og tómati ofan á']::text[]),
('d103db81-af8c-499e-8e8b-fb385d50298d'::uuid, 'Eggjakaka með grænmeti', 'Full af grænmeti og próteini — fjölhæf og fljótleg.', array['3 egg','15 g spínat','30 g sveppir','35 g fetaostur','1 tsk. smjör']::text[], array['Þeyttu eggin í skál.','Steiktu spínat og sveppi upp úr smjörinu.','Helltu eggjunum yfir grænmetið.','Stráðu fetaosti yfir, brjóttu saman og berðu fram.']::text[]),
('d15c5ff9-f2d7-413e-b4ca-e25d9b117c22'::uuid, 'Ofnbakaður þorskur með kúskúsi', 'Léttur og magur hvítur fiskur með mjúku kúskúsi.', array['180 g þorskflak','130 g kúskús','½ sítróna','hvítlaukur','ólífuolía','kirsuberjatómatar','steinselja']::text[], array['Hitaðu ofninn í 200 °C.','Settu þorskinn í eldfast mót og dreifðu hvítlauk, sítrónu og ólífuolíu yfir.','Bakaðu í 12 mínútur.','Útbúðu kúskúsið með sjóðandi vatni.','Bættu tómötum og steinselju út í.','Berðu fram saman.']::text[]),
('f2b4ed1f-be42-4a6a-b6c1-f5ab74550fd8'::uuid, 'Bolognese með nautahakki', 'Ítalskur sígildur réttur, próteinríkur og saðsamur.', array['200 g magurt nautahakk','1 laukur','2 hvítlauksrif','1 dós saxaðir tómatar','1 gulrót, rifin','pasta','parmesanostur']::text[], array['Sjóddu vatn fyrir pastað.','Steiktu lauk, hvítlauk og gulrót.','Bættu hakkinu út í og brúnaðu það.','Helltu tómötunum út í og láttu malla í 15 mínútur.','Sjóddu pastað og helltu vatninu af.','Blandaðu saman og stráðu parmesanosti yfir.']::text[]),
('d2c8c182-b66f-402e-9d14-d210b001e99a'::uuid, 'Wok-steikt nautakjöt með kínóa', 'Magurt nautakjöt og grænmeti á kínóa — próteinríkur og glútenlaus kvöldmatur.', array['200 g magrir nautakjötsstrimlar','80 g kínóa (ósoðið)','100 g sveppir','200 g spergilkál','2 msk. sojasósa','hvítlaukur','engifer','sesamolía']::text[], array['Sjóddu kínóa í 12 mín.','Steiktu kjötið í 3 mín. við háan hita','Bættu grænmeti, hvítlauk og engifer út í','Bættu sojasósu og sesamolíu út í','Berðu fram á kínóa']::text[]),
('cf358415-65a6-4aab-b8bd-b12f82037528'::uuid, 'Kjúklingakarrí með hrísgrjónum', 'Milt og notalegt — fellur flestum vel í geð.', array['200 g kjúklingabringa','1 laukur','1 dós kókosmjólk','2 msk. karrímauk','140 g basmatíhrísgrjón','ferskt kóríander']::text[], array['Sjóddu hrísgrjónin samkvæmt leiðbeiningum á umbúðum.','Skerðu kjúkling og lauk í sneiðar.','Steiktu laukinn og bættu karrímaukinu út í.','Bættu kjúklingnum út í og steiktu í 5 mínútur.','Helltu kókosmjólkinni út í og láttu malla í 10 mínútur.','Berðu fram á hrísgrjónum með kóríander.']::text[]),
('01a4c9d5-dbd3-420c-b878-70dd836957f8'::uuid, 'Kókoskarrí með kjúklingi og hrísgrjónum', 'Milt karrí að taílenskum hætti með kjúklingalærum og jasmínhrísgrjónum.', array['200 g kjúklingalæri','100 g jasmínhrísgrjón (ósoðin)','2 dl kókosmjólk','2 msk. rautt karrímauk','1 paprika','100 g spínat','límóna','kóríander']::text[], array['Sjóddu hrísgrjónin','Brúnaðu kjúklinginn í 3 mín.','Bættu karrímaukinu út í og steiktu í 1 mín.','Bættu kókosmjólk og papriku út í og láttu malla í 12 mín.','Hrærðu spínatinu saman við svo það mýkist','Berðu fram á hrísgrjónum með límónu']::text[]),
('d8e3b8f5-1446-4873-9ce9-a80d38e109e5'::uuid, 'Ofnréttur með þorski og kartöflum', 'Þorskflök bökuð með kartöflum, blaðlauk og dilli — einfalt og gott.', array['250 g þorskflak','300 g kartöflur','1 blaðlaukur','3 msk. ólífuolía','sítróna','dill','salt','svartur pipar']::text[], array['Skerðu kartöflurnar í þunnar sneiðar','Raðaðu þeim með blaðlauknum í olíuborið eldfast mót','Bakaðu í 25 mín. við 200 °C','Leggðu þorskflakið ofan á og bakaðu í 12 mín. til viðbótar','Stráðu dilli yfir og kreistu sítrónu yfir']::text[]),
('6cd76fe8-e00a-4443-9539-aa923ce321ab'::uuid, 'Sítrónukjúklingur með kínóa og aspas', 'Ferskur og léttur kvöldmatur með kjúklingabringu í aðalhlutverki.', array['200 g kjúklingabringa','80 g kínóa (ósoðið)','200 g aspas','ólífuolía','sítróna','rósmarín','tímían','hvítlaukur']::text[], array['Marineraðu kjúklinginn í olíu, sítrónu og kryddjurtum í 10 mín.','Sjóddu kínóa í 12 mín.','Steiktu kjúklinginn á pönnu í 6 mín. á hvorri hlið','Gufusjóddu aspasinn í 4 mín.']::text[]),
('8acd79f6-9ca2-4098-b25f-761e64ead599'::uuid, 'Pönnusteiktur silungur með grænkáli', 'Silungsflak á mýktu grænkáli með hvítlauk og sítrónu — léttur og kolvetnalítill kvöldmatur.', array['200 g silungsflak','200 g grænkál','2 hvítlauksrif','sítróna','ólífuolía','svartur pipar','sjávarsalt']::text[], array['Steiktu silunginn á pönnu í 4 mín. á hvorri hlið','Steiktu grænkálið með hvítlauk í olíu í 4 mín.','Kreistu sítrónu yfir hvort tveggja']::text[]),
('f2cede32-d8df-41c7-88a4-299d9e406987'::uuid, 'Ofnbakaður lax með kartöflum og spergilkáli', 'Lax á ofnplötu — lítil fyrirhöfn, heil máltíð.', array['200 g laxaflak','250 g smælki','200 g spergilkál','ólífuolía','sítróna','dill','salt']::text[], array['Skerðu kartöflurnar í tvennt og veltu þeim upp úr olíu','Bakaðu í 20 mín. við 200 °C','Bættu laxi og spergilkáli á plötuna og bakaðu í 12 mín. til viðbótar','Kreistu sítrónu yfir']::text[]),
('9a7f9b31-770e-4f09-a434-fdcc5612f6c9'::uuid, 'Lax með ofnbökuðu grænmeti', 'Ómega-3, prótein og grænmeti — hinn fullkomni kvöldmatur.', array['180 g laxaflak','100 g spergilkál','150 g smælki','ólífuolía','sítróna','hvítlaukur','salt og pipar']::text[], array['Hitaðu ofninn í 200 °C.','Veltu grænmetinu upp úr ólífuolíu, salti og hvítlauk.','Bakaðu í 25 mínútur.','Bættu laxinum við og kreistu sítrónu yfir.','Bakaðu í 12 mínútur til viðbótar.']::text[]),
('433cbd75-4826-4262-8e0f-314300f5f1c5'::uuid, 'Kjúklingafajitas á ofnplötu', 'Ein plata, lítið uppvask og mikið bragð.', array['200 g kjúklingabringa','1 paprika','1 laukur','1 msk. ólífuolía','fajitas-krydd','2 heilhveititortillur','límóna']::text[], array['Hitaðu ofninn í 220 °C.','Skerðu allt í strimla.','Veltu því upp úr olíu og kryddi á ofnplötu.','Bakaðu í 20 mínútur.','Vefðu inn í tortillur og kreistu límónu yfir.']::text[]),
('7ebc47a6-9338-4650-848a-e7d719ebf7bc'::uuid, 'Hægeldað lambakjöt í skál', 'Meyrt lambakjöt með kúskúsi, ofnbökuðu grænmeti og jógúrtsósu.', array['200 g lambabógur, skorinn í bita','80 g kúskús (ósoðið)','1 kúrbítur','1 paprika','100 g grísk jógúrt','mynta','broddkúmen','hvítlaukur']::text[], array['Brúnaðu kjötið í 5 mín.','Hægeldaðu það í soði í 90 mín.','Bakaðu grænmetið í ofni í 25 mín. við 200 °C','Útbúðu kúskúsið','Hrærðu jógúrtina saman við myntu og hvítlauk','Settu allt saman í skál']::text[]),
('07c092ab-0ec6-484d-b61b-77078d08c368'::uuid, 'Lambapottréttur í hægeldunarpotti', 'Lambakjöt með rótargrænmeti og kryddjurtum í soði — sett í pottinn og látið eiga sig.', array['200 g lambabógur, skorinn í bita','1 gulrót','1 nípa','1 laukur','2 kartöflur','5 dl lambasoð','rósmarín','lárviðarlauf','ólífuolía']::text[], array['Brúnaðu kjötið í 5 mín.','Bættu söxuðu grænmeti, soði og kryddjurtum út í','Hægeldaðu í 4 klst. á lágum hita','Smakkaðu til']::text[]),
('d878e808-a062-4215-9693-2dd364a62686'::uuid, 'Wok-steikt nautakjöt með grænmeti', 'Fljótlegur wok-réttur með miklu grænmeti og mögru nautakjöti.', array['180 g nautasteik','300 g blandað wok-grænmeti','2 msk. sojasósa','1 msk. ostrusósa','1 msk. sesamolía','engifer','140 g jasmínhrísgrjón']::text[], array['Sjóddu hrísgrjónin.','Skerðu kjötið í þunnar sneiðar.','Hitaðu olíuna á wok-pönnu, steiktu kjötið í 2 mínútur og taktu það til hliðar.','Steiktu grænmetið í 4 mínútur.','Settu kjötið aftur á pönnuna og bættu sósunum út í.','Berðu fram á hrísgrjónum.']::text[]),
('5fb152f9-3436-4fff-88ff-b39cb161d8f0'::uuid, 'Fylltar paprikur', 'Paprikur fylltar með kalkúnahakki, hrísgrjónum og osti — notalegur og próteinríkur réttur.', array['4 paprikur','200 g kalkúnahakk','100 g soðin hrísgrjón','100 g saxaðir tómatar','60 g cheddarostur','1 laukur','hvítlaukur','ólífuolía']::text[], array['Skerðu paprikurnar í tvennt og fræhreinsaðu þær','Brúnaðu hakkið með lauknum','Blandaðu hrísgrjónum og tómötum saman við','Fylltu paprikurnar og stráðu osti yfir','Bakaðu í 25 mín. við 200 °C']::text[]),
('e7addb6b-6d15-47cf-9eed-ad12ad8549ae'::uuid, 'Kalkúnabollur og pasta', 'Léttara en nautakjöt en jafn saðsamt.', array['200 g kalkúnahakk','1 egg','brauðrasp','parmesanostur','1 krukka pastasósa','spagettí','basilíka']::text[], array['Blandaðu hakkinu saman við egg, brauðrasp og parmesanost.','Mótaðu 8 bollur.','Brúnaðu þær á pönnu.','Bættu sósunni út í og láttu malla í 10 mínútur.','Sjóddu spagettíið.','Berðu bollurnar fram á pastanu með basilíku.']::text[]),
('33753b36-955e-4f41-931a-d701e2393580'::uuid, 'Kjúklingabaunakarrí með grænmeti', 'Próteinríkur vegan kvöldmatur sem hittir í mark.', array['1 dós kjúklingabaunir','1 dós saxaðir tómatar','1 laukur','2 hvítlauksrif','karríduft','30 g spínat','140 g hrísgrjón']::text[], array['Sjóddu hrísgrjónin.','Steiktu lauk og hvítlauk.','Bættu karríduftinu út í.','Helltu tómötum og kjúklingabaunum út í.','Láttu malla í 15 mínútur.','Hrærðu spínatinu saman við.','Berðu fram á hrísgrjónum.']::text[]),
('24301740-bae8-4641-8bd9-beb4ce553d19'::uuid, 'Grænmetisskál með próteini', 'Svartbaunabuff á kínóa með avókadói, salsasósu og fetaosti.', array['1 svartbaunabuff (170 g)','80 g kínóa (ósoðið)','½ avókadó','3 msk. salsasósa','100 g fetaostur','blandað salat','límóna']::text[], array['Sjóddu kínóa','Steiktu buffið á pönnu í 3 mín. á hvorri hlið','Raðaðu kínóa, salati, buffi, avókadói, salsasósu og muldum fetaosti í skál']::text[]),
('50ba5147-0b67-4191-b4c8-6ec3c4dfaafd'::uuid, 'Nautahakk og sæt kartafla í skál', 'Magurt nautakjöt, sæt kartafla og grænmeti — litríkt og saðsamt.', array['150 g magurt nautahakk','1 meðalstór sæt kartafla','30 g spínat','1 msk. ólífuolía','paprikuduft','hvítlauksduft','salt']::text[], array['Skerðu sætu kartöfluna í teninga og bakaðu í ofni (200 °C, 20 mín.).','Hitaðu ólífuolíu á pönnu og brúnaðu hakkið með kryddinu.','Bættu spínatinu út í svo það mýkist.','Settu allt saman í skál.']::text[]),
('52de9984-b0ff-4717-a968-d63419011c75'::uuid, 'Nautakjöt og spergilkál á wok með hrísgrjónum', 'Magurt nautakjöt með spergilkáli og papriku á jasmínhrísgrjónum.', array['150 g magrir nautakjötsstrimlar','200 g spergilkál','1 paprika','100 g jasmínhrísgrjón (ósoðin)','2 msk. sojasósa','1 hvítlauksrif','1 tsk. sesamolía','engifer']::text[], array['Sjóddu hrísgrjónin','Steiktu kjötið í 3 mín. við háan hita','Bættu grænmeti, hvítlauk og engifer út í','Bættu sojasósu og sesamolíu út í','Berðu fram á hrísgrjónum']::text[]),
('b83d25d8-259f-412a-8a97-81ac9aae1f14'::uuid, 'Sesarsalat með kjúklingi', 'Grillaður kjúklingur á romaine-salati með parmesanosti og stökkum heilhveitibrauðteningum.', array['200 g kjúklingabringa','1 romaine-salathaus','30 g parmesanostur','30 g heilhveitibrauðteningar','3 msk. sesarsósa','svartur pipar']::text[], array['Grillaðu kjúklinginn í 5 mín. á hvorri hlið','Skerðu hann í sneiðar','Veltu salatinu upp úr sósunni','Settu kjúkling, parmesanost og brauðteninga ofan á']::text[]),
('8076bcd2-3d19-4c91-8395-ab141b70c91d'::uuid, 'Létt sesarsalat', 'Vinsæll veitingahúsaréttur í léttari útgáfu heima.', array['150 g grillaður kjúklingur','romaine-salat','2 msk. rifinn parmesanostur','1 msk. sesarsósa','0,5 dl brauðteningar']::text[], array['Grillaðu eða steiktu kjúklinginn og skerðu hann í sneiðar.','Rífðu salatið í skál.','Settu kjúkling, parmesanost og brauðteninga ofan á.','Dreifðu sósunni yfir og blandaðu saman.']::text[]),
('8c29edef-0e76-4c71-90cf-b04eda7d538e'::uuid, 'Kjúklingaskál með hrísgrjónum', 'Klassíski nestisrétturinn: kjúklingur, hrísgrjón og grænmeti.', array['150 g kjúklingabringa','120 g soðin hrísgrjón','100 g spergilkál','1 msk. sojasósa','1 tsk. sesamolía','1 hvítlauksrif']::text[], array['Skerðu kjúklinginn í sneiðar og kryddaðu hann.','Hitaðu sesamolíu á pönnu og bættu hvítlauknum út í.','Steiktu kjúklinginn þar til hann er eldaður í gegn.','Gufusjóddu spergilkálið í 4 mínútur.','Settu allt á hrísgrjónin og helltu sojasósu yfir.']::text[]),
('b33eced5-864a-47cb-b593-ebbeeb8c1096'::uuid, 'Þorskur með hrísgrjónum', 'Pönnusteiktur þorskur með gufusoðnu grænmeti á jasmínhrísgrjónum með sojasósu.', array['200 g þorskflak','100 g jasmínhrísgrjón (ósoðin)','100 g pak choi eða spínat','2 msk. sojasósa','1 vorlaukur','1 tsk. sesamolía','engifer']::text[], array['Sjóddu hrísgrjónin','Steiktu þorskinn á pönnu í 4 mín. á hvorri hlið','Gufusjóddu grænmetið í 2 mín.','Settu allt saman, dreifðu sojasósu og sesamolíu yfir og stráðu vorlauk ofan á']::text[]),
('cffb65b5-38c8-48c6-a3e1-1c7f587f1dc9'::uuid, 'Steikt hrísgrjón með eggi', 'Fljótlegt og saðsamt — og nýtir afgangshrísgrjón.', array['150 g köld soðin hrísgrjón','2 egg','150 g blandað grænmeti','2 msk. sojasósa','1 msk. sesamolía','2 vorlaukar']::text[], array['Hitaðu olíuna á wok-pönnu og hrærðu eggin.','Bættu hrísgrjónum og grænmeti út í og steiktu.','Bættu sojasósunni út í.','Stráðu vorlauk yfir.']::text[]),
('6fdc6ba9-34fd-4dd8-bf93-574f0fbd7878'::uuid, 'Salatskál með eggjum, baunum og fetaosti', 'Próteinrík grænmetisskál með nýrnabaunum, harðsoðnum eggjum og fetaosti.', array['200 g soðnar nýrnabaunir','3 harðsoðin egg','30 g fetaostur','blandað salat','1 tómatur','ólífuolía','rauðvínsedik','svartur pipar']::text[], array['Skerðu eggin í tvennt','Blandaðu salati, baunum og tómati saman með olíu og ediki','Settu eggin og mulinn fetaost ofan á']::text[]),
('50758373-02d8-4062-b1d6-e43e51c599a7'::uuid, 'Linsubaunasúpa með kjúklingi', 'Matarmikil súpa með kjúklingabringu og rauðum linsubaunum, án mjólkurvara og glútens.', array['150 g kjúklingabringa, skorin í bita','100 g rauðar linsubaunir','1 gulrót','1 laukur','5 dl kjúklingasoð','1 tsk. broddkúmen','ólífuolía']::text[], array['Steiktu lauk og gulrót í olíu í 5 mín.','Bættu kjúklingnum út í og brúnaðu í 3 mín.','Bættu linsubaunum, soði og broddkúmeni út í','Láttu malla í 20 mín.']::text[]),
('8072f8b1-4d72-46d2-97cf-32013e148f70'::uuid, 'Linsubaunasúpa', 'Matarmikil og trefjarík súpa með grænmetispróteini.', array['200 g rauðar linsubaunir','1 laukur','2 gulrætur','7 dl grænmetissoð','broddkúmen','túrmerik','1 msk. ólífuolía']::text[], array['Steiktu lauk og gulrætur í ólífuolíu.','Bættu kryddi og linsubaunum út í.','Helltu soðinu út í.','Láttu malla í 25 mínútur þar til baunirnar eru mjúkar.','Maukaðu helminginn svo súpan verði rjómakenndari.']::text[]),
